-- Maison Signature : rayons Femme / Homme, univers transverses (Sacs, Chaussures, Montres…)
ALTER TABLE categories ADD COLUMN universe VARCHAR(30);
CREATE INDEX idx_categories_universe ON categories(universe);

-- Racines
UPDATE categories SET position = 1 WHERE slug = 'femme';

-- Rayon Femme : les univers passent directement sous « Femme »
UPDATE categories SET name = 'Sacs', parent_id = (SELECT id FROM categories WHERE slug = 'femme'), position = 1 WHERE slug = 'sacs-femme';
UPDATE categories SET position = 2 WHERE slug = 'chaussures-femme';
UPDATE categories SET position = 3 WHERE slug = 'vetements-femme';
UPDATE categories SET position = 6 WHERE slug = 'accessoires-femme';
UPDATE categories SET position = 1 WHERE slug = 'portefeuilles-femme';
UPDATE categories SET position = 2 WHERE slug = 'ceintures-femme';
UPDATE categories SET position = 3 WHERE slug = 'bijoux-femme';

-- Rayon Homme

-- Univers : chaque rayon et ses sous-rubriques
UPDATE categories SET universe = 'sacs' WHERE id IN (
    WITH RECURSIVE d AS (SELECT id FROM categories WHERE slug IN ('sacs-femme','sacs-homme')
                         UNION ALL SELECT c.id FROM categories c JOIN d ON c.parent_id = d.id)
    SELECT id FROM d);
UPDATE categories SET universe = 'chaussures' WHERE id IN (
    WITH RECURSIVE d AS (SELECT id FROM categories WHERE slug IN ('chaussures-femme','chaussures-homme')
                         UNION ALL SELECT c.id FROM categories c JOIN d ON c.parent_id = d.id)
    SELECT id FROM d);
